      "gene_symbol": "GATAD2A",
      "confidence": 0.85,
      "cited_ids": [
        "pub:21490301",
        "pub:20439494"
      ],
      "rationale": "Pre-cutoff studies demonstrated that the coiled-coil interaction of GATAD2A (p66alpha) with MBD2 is critical for NuRD complex recruitment and globin gene silencing, supporting the post-cutoff discovery that perturbing GATAD2A derepresses fetal hemoglobin."
    },
    {
      "gene_symbol": "EIF2AK1",
      "confidence": 0.8,
      "cited_ids": [
        "pub:15931390",
        "pub:22498744"
      ],
      "rationale": "EIF2AK1 (HRI) is an erythroid-enriched kinase that modifies the phenotypic severity of beta-thalassemia and activates the Atf4 pathway during erythropoiesis, supporting its establishment as a regulator of fetal hemoglobin."
    },
    {
      "gene_symbol": "ATF4",
      "confidence": 0.7,
      "cited_ids": [
        "pub:22498744",
        "pub:18955481"
      ],
      "rationale": "ATF4 functions downstream of heme-regulated eIF2alpha kinase (HRI) and is required for definitive erythropoiesis, indicating a functional regulatory role in the erythroid stress and globin expression axis."
    },
    {
      "gene_symbol": "ZBTB7A",
      "confidence": 0.65,
      "cited_ids": [
        "pub:19853566",
        "pub:23134786"
      ],
      "rationale": "ZBTB7A (LRF) was established prior to the cutoff as an essential downstream target of GATA1 in erythroid development and differentiation, supporting its prospective role in erythroid globin gene regulation."
    }
  ],
